            'average' => null,
            'baseVolume' => $baseVolume,
            'quoteVolume' => $quoteVolume,
            'info' => $ticker,
        ), $market);
    }

    public function watch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbol, $timeframe, $since, $limit, $params) {
            /**
             * watches historical candlestick data containing the open, high, low, and close price, and the volume of a $market
             * @param {string} $symbol unified $symbol of the $market to fetch OHLCV data for
             * @param {string} $timeframe the length of time each candle represents
             * @param {int} [$since] timestamp in ms of the earliest candle to fetch
             * @param {int} [$limit] the maximum amount of candles to fetch
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {int[][]} A list of candles ordered, open, high, low, close, volume
             */
            Async\await($this->load_markets());
            $market = $this->market($symbol);
            $symbol = $market['symbol'];
            $url = $this->urls['api']['ws'];
            $marketId = $market['id'];
            $interval = $this->safe_string($this->timeframes, $timeframe, $timeframe);
            $messageHash = 'ohlcv:' . $timeframe . ':' . $symbol;
            $request = array(
                'method' => 'SUBSCRIBE',
                'params' => array(
                    strtolower($marketId) . '@kline_' . $interval,
                ),
                'id' => $this->request_id(),
            );
            $message = $this->extend($request, $params);
            $ohlcv = Async\await($this->watch($url, $messageHash, $message, $messageHash));
            if ($this->newUpdates) {
                $limit = $ohlcv->getLimit ($symbol, $limit);
            }
            return $this->filter_by_since_limit($ohlcv, $since, $limit, 0, true);
        }) ();
    }

    public function handle_ohlcv(Client $client, $message) {
        //
        //     {
        //         "e" => "kline",
        //         "E" => 1638747328000,
        //         "s" => "BTCUSDT",
        //         "k" => {
        //             "t" => 1638747300000,
        //             "T" => 1638747359999,
        //             "s" => "BTCUSDT",
        //             "i" => "1m",
        //             "f" => 12340,
        //             "L" => 12345,
        //             "o" => "49000.00",
        //             "c" => "50000.00",
        //             "h" => "51000.00",
        //             "l" => "48000.00",
        //             "v" => "10000.0",
        //             "n" => 6,
        //             "x" => false,
        //             "q" => "495000000.0",
        //             "V" => "5000.0",
        //             "Q" => "247500000.0"
        //         }
        //     }
        //
        $kline = $this->safe_dict($message, 'k', array());
        $marketId = $this->safe_string($kline, 's');
        $market = $this->safe_market($marketId);
        $symbol = $market['symbol'];
        $interval = $this->safe_string($kline, 'i');
        $timeframe = $this->find_timeframe($interval);
        $parsed = array(
            $this->safe_integer($kline, 't'),
            $this->safe_number($kline, 'o'),
            $this->safe_number($kline, 'h'),
            $this->safe_number($kline, 'l'),
            $this->safe_number($kline, 'c'),
            $this->safe_number($kline, 'v'),
        );
        $messageHash = 'ohlcv:' . $timeframe . ':' . $symbol;
        $this->ohlcvs[$symbol] = $this->safe_dict($this->ohlcvs, $symbol, array());
        $stored = $this->safe_value($this->ohlcvs[$symbol], $timeframe);
        if ($stored === null) {
            $limit = $this->safe_integer($this->options, 'OHLCVLimit', 1000);
            $stored = new ArrayCacheByTimestamp ($limit);
            $this->ohlcvs[$symbol][$timeframe] = $stored;
        }
        $stored->append ($parsed);
        $client->resolve ($stored, $messageHash);
    }

    public function watch_balance($params = array ()): PromiseInterface {
        return Async\async(function () use ($params) {
            /**
             * watch balance and get the amount of funds available for trading or funds locked in orders
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array} a ~@link https://docs.ccxt.com/#/?id=balance-structure balance structure~
             */
            Async\await($this->load_markets());
            Async\await($this->authenticate($params));
            $url = $this->urls['api']['ws'];
            $listenKey = $this->safe_string($this->options, 'listenKey');
            $messageHash = 'balance';
            return Async\await($this->watch($url . '/' . $listenKey, $messageHash, null, $messageHash));
        }) ();
    }

    public function handle_balance(Client $client, $message) {
        //
        //     {
        //         "e" => "ACCOUNT_UPDATE",
        //         "E" => 1638747328000,
        //         "a" => {
        //             "B" => array(
        //                 {
        //                     "a" => "USDT",
        //                     "wb" => "10000.00000000",
        //                     "cw" => "9500.00000000"
        //                 }
        //             )
        //         }
        //     }
        //
        $accountData = $this->safe_dict($message, 'a', array());
        $balances = $this->safe_list($accountData, 'B', array());
        for ($i = 0; $i < count($balances); $i++) {
            $balance = $balances[$i];
            $currencyId = $this->safe_string($balance, 'a');
            $code = $this->safe_currency_code($currencyId);
            $account = $this->account();
            $account['free'] = $this->safe_string($balance, 'cw');
            $account['total'] = $this->safe_string($balance, 'wb');
            $this->balance[$code] = $account;
        }
        $this->balance = $this->safe_balance($this->balance);
        $messageHash = 'balance';
        $client->resolve ($this->balance, $messageHash);
    }

    public function watch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbol, $since, $limit, $params) {
            /**
             * watches information on multiple $orders made by the user
             * @param {string} $symbol unified market $symbol of the market $orders were made in
             * @param {int} [$since] the earliest time in ms to fetch $orders for
             * @param {int} [$limit] the maximum number of order structures to retrieve
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
             */
            Async\await($this->load_markets());
            Async\await($this->authenticate($params));
            $url = $this->urls['api']['ws'];
            $listenKey = $this->safe_string($this->options, 'listenKey');
            $messageHash = 'orders';
            if ($symbol !== null) {
                $symbol = $this->symbol($symbol);
                $messageHash .= ':' . $symbol;
