        $order = $this->parse_ws_order($orderData);
        $symbol = $order['symbol'];
        if ($this->orders === null) {
            $limit = $this->safe_integer($this->options, 'ordersLimit', 1000);
            $this->orders = new ArrayCacheBySymbolById ($limit);
        }
        $orders = $this->orders;
        $orders->append ($order);
        $messageHash = 'orders';
        $client->resolve ($orders, $messageHash);
        $messageHash .= ':' . $symbol;
        $client->resolve ($orders, $messageHash);
    }

    public function parse_ws_order($order, $market = null) {
        //
        //     {
        //         "s" => "BTCUSDT",
        //         "c" => "client_order_id",
        //         "S" => "BUY",
        //         "o" => "LIMIT",
        //         "f" => "GTC",
        //         "q" => "1.5",
        //         "p" => "50000.00",
        //         "ap" => "0",
        //         "sp" => "0",
        //         "x" => "NEW",
        //         "X" => "NEW",
        //         "i" => 12345,
        //         "l" => "0",
        //         "z" => "0",
        //         "L" => "0",
        //         "T" => 1638747327000,
        //         "t" => 0
        //     }
        //
        $id = $this->safe_string($order, 'i');
        $clientOrderId = $this->safe_string($order, 'c');
        $marketId = $this->safe_string($order, 's');
        $market = $this->safe_market($marketId, $market);
        $symbol = $market['symbol'];
        $side = $this->safe_string_lower($order, 'S');
        $type = $this->safe_string_lower($order, 'o');
        $price = $this->safe_string($order, 'p');
        $amount = $this->safe_string($order, 'q');
        $filled = $this->safe_string($order, 'z');
        $average = $this->safe_string($order, 'ap');
        $timestamp = $this->safe_integer($order, 'T');
        $rawStatus = $this->safe_string($order, 'X');
        $status = $this->parse_order_status($rawStatus);
        $timeInForce = $this->safe_string($order, 'f');
        return $this->safe_order(array(
            'info' => $order,
            'id' => $id,
            'clientOrderId' => $clientOrderId,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'symbol' => $symbol,
            'type' => $type,
            'side' => $side,
            'price' => $price,
            'amount' => $amount,
            'cost' => null,
            'average' => $average,
            'filled' => $filled,
            'remaining' => null,
            'status' => $status,
            'fee' => null,
            'trades' => null,
            'timeInForce' => $timeInForce,
            'postOnly' => null,
            'reduceOnly' => null,
        ), $market);
    }

    public function watch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbol, $since, $limit, $params) {
            /**
             * watches information on multiple $trades made by the user
             * @param {string} $symbol unified market $symbol of the market $trades were made in
             * @param {int} [$since] the earliest time in ms to fetch $trades for
             * @param {int} [$limit] the maximum number of trade structures to retrieve
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=trade-structure trade structures~
             */
            Async\await($this->load_markets());
            Async\await($this->authenticate($params));
            $url = $this->urls['api']['ws'];
            $listenKey = $this->safe_string($this->options, 'listenKey');
            $messageHash = 'myTrades';
            if ($symbol !== null) {
                $symbol = $this->symbol($symbol);
                $messageHash .= ':' . $symbol;
            }
            $trades = Async\await($this->watch($url . '/' . $listenKey, $messageHash, null, $messageHash));
            if ($this->newUpdates) {
                $limit = $trades->getLimit ($symbol, $limit);
            }
            return $this->filter_by_symbol_since_limit($trades, $symbol, $since, $limit, true);
        }) ();
    }

    public function handle_my_trade(Client $client, $message) {
        //
        //     {
        //         "e" => "ORDER_TRADE_UPDATE",
        //         "E" => 1638747328000,
        //         "o" => {
        //             "s" => "BTCUSDT",
        //             "c" => "client_order_id",
        //             "S" => "BUY",
        //             "o" => "LIMIT",
        //             "f" => "GTC",
        //             "q" => "1.5",
        //             "p" => "50000.00",
        //             "x" => "TRADE",
        //             "X" => "PARTIALLY_FILLED",
        //             "i" => 12345,
        //             "l" => "1.0",
        //             "z" => "1.0",
        //             "L" => "50000.00",
        //             "n" => "10.00",
        //             "N" => "USDT",
        //             "T" => 1638747327000,
        //             "t" => 67890
        //         }
        //     }
        //
        $orderData = $this->safe_dict($message, 'o', array());
        $executionType = $this->safe_string($orderData, 'x');
        if ($executionType !== 'TRADE') {
            return;
        }
        $trade = $this->parse_ws_my_trade($orderData);
        $symbol = $trade['symbol'];
        if ($this->myTrades === null) {
            $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $this->myTrades = new ArrayCacheBySymbolById ($limit);
        }
        $myTrades = $this->myTrades;
        $myTrades->append ($trade);
        $messageHash = 'myTrades';
        $client->resolve ($myTrades, $messageHash);
        $messageHash .= ':' . $symbol;
        $client->resolve ($myTrades, $messageHash);
    }

    public function parse_ws_my_trade($trade, $market = null) {
        //
        //     {
        //         "s" => "BTCUSDT",
        //         "c" => "client_order_id",
        //         "S" => "BUY",
        //         "o" => "LIMIT",
        //         "l" => "1.0",
        //         "z" => "1.0",
        //         "L" => "50000.00",
        //         "n" => "10.00",
        //         "N" => "USDT",
        //         "T" => 1638747327000,
        //         "t" => 67890,
        //         "i" => 12345
        //     }
        //
        $id = $this->safe_string($trade, 't');
        $orderId = $this->safe_string($trade, 'i');
        $marketId = $this->safe_string($trade, 's');
        $market = $this->safe_market($marketId, $market);
        $symbol = $market['symbol'];
        $side = $this->safe_string_lower($trade, 'S');
        $type = $this->safe_string_lower($trade, 'o');
        $price = $this->safe_string($trade, 'L');
        $amount = $this->safe_string($trade, 'l');
        $timestamp = $this->safe_integer($trade, 'T');
        $feeCost = $this->safe_string($trade, 'n');
        $feeCurrency = $this->safe_currency_code($this->safe_string($trade, 'N'));
        $fee = null;
        if ($feeCost !== null) {
            $fee = array(
                'cost' => $feeCost,
                'currency' => $feeCurrency,
            );
        }
        return $this->safe_trade(array(
            'info' => $trade,
            'id' => $id,
            'order' => $orderId,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $symbol,
            'type' => $type,
            'side' => $side,
            'takerOrMaker' => null,
            'price' => $price,
            'amount' => $amount,
            'cost' => null,
            'fee' => $fee,
        ), $market);
    }

    public function watch_positions(?array $symbols = null, ?int $since = null, ?int $limit = null, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbols, $since, $limit, $params) {
            /**
             * watch all open $positions
             * @param {string[]} [$symbols] list of unified market $symbols
             * @param {int} [$since] the earliest time in ms to fetch $positions for
             * @param {int} [$limit] the maximum number of $positions to retrieve
             * @param {array} $params extra parameters specific to the exchange API endpoint
             * @return {array[]} a list of {@link https://docs.ccxt.com/en/latest/manual.html#position-structure position structure}
             */
            Async\await($this->load_markets());
            Async\await($this->authenticate($params));
            $url = $this->urls['api']['ws'];
            $listenKey = $this->safe_string($this->options, 'listenKey');
            $messageHash = 'positions';
            $positions = Async\await($this->watch($url . '/' . $listenKey, $messageHash, null, $messageHash));
            return $this->filter_by_symbols_since_limit($positions, $symbols, $since, $limit, true);
        }) ();
    }

    public function handle_position(Client $client, $message) {
        //
        //     {
        //         "e" => "ACCOUNT_UPDATE",
        //         "E" => 1638747328000,
        //         "a" => {
        //             "P" => array(
        //                 {
        //                     "s" => "BTCUSDT",
        //                     "pa" => "1.5",
        //                     "ep" => "50000.00",
        //                     "up" => "1500.00",
        //                     "mt" => "cross",
        //                     "iw" => "0",
        //                     "ps" => "BOTH"
        //                 }
        //             )
        //         }
        //     }
        //
        $account = $this->safe_dict($message, 'a', array());
        $rawPositions = $this->safe_list($account, 'P', array());
        if ($this->positions === null) {
            $this->positions = new ArrayCacheBySymbolById ();
        }
        $cache = $this->positions;
        for ($i = 0; $i < count($rawPositions); $i++) {
            $rawPosition = $rawPositions[$i];
            $position = $this->parse_ws_position($rawPosition);
            $cache->append ($position);
        }
        $messageHash = 'positions';
        $client->resolve ($cache, $messageHash);
    }

    public function parse_ws_position($position, $market = null) {
        //
        //     {
        //         "s" => "BTCUSDT",
        //         "pa" => "1.5",
        //         "ep" => "50000.00",
        //         "up" => "1500.00",
        //         "mt" => "cross",
        //         "iw" => "0",
        //         "ps" => "BOTH"
        //     }
        //
        $marketId = $this->safe_string($position, 's');
        $market = $this->safe_market($marketId, $market);
        $symbol = $market['symbol'];
        $contracts = $this->safe_string($position, 'pa');
        $entryPrice = $this->safe_string($position, 'ep');
        $unrealizedPnl = $this->safe_string($position, 'up');
        $marginType = $this->safe_string($position, 'mt');
        $side = $this->safe_string($position, 'ps');
        return $this->safe_position(array(
            'info' => $position,
            'id' => null,
            'symbol' => $symbol,
            'contracts' => $contracts,
            'contractSize' => null,
            'unrealizedPnl' => $unrealizedPnl,
            'leverage' => null,
            'liquidationPrice' => null,
            'collateral' => null,
            'notional' => null,
            'markPrice' => null,
            'entryPrice' => $entryPrice,
            'timestamp' => null,
            'initialMargin' => null,
            'initialMarginPercentage' => null,
            'maintenanceMargin' => null,
            'maintenanceMarginPercentage' => null,
            'marginRatio' => null,
            'datetime' => null,
            'marginMode' => $marginType,
            'side' => $side,
            'hedged' => null,
            'percentage' => null,
        ));
    }

    public function authenticate($params = array ()) {
        return Async\async(function () use ($params) {
            $response = Async\await($this->fapiPrivatePostListenKey ($params));
            $listenKey = $this->safe_string($response, 'listenKey');
            $this->options['listenKey'] = $listenKey;
            $refreshRate = $this->safe_integer($this->options, 'listenKeyRefreshRate', 1200000);
            $this->delay($refreshRate, array($this, 'keep_alive_listen_key'), $params);
            return $listenKey;
        }) ();
    }

    public function keep_alive_listen_key($params = array ()) {
        return Async\async(function () use ($params) {
            Async\await($this->fapiPrivatePutListenKey ($params));
            $refreshRate = $this->safe_integer($this->options, 'listenKeyRefreshRate', 1200000);
            $this->delay($refreshRate, array($this, 'keep_alive_listen_key'), $params);
        }) ();
    }

    public function handle_message(Client $client, $message) {
        //
        //     {
        //         "e" => "depthUpdate",
        //         "s" => "BTCUSDT",
        //         ...
        //     }
        //
        //     PONG response:
        //     {
        //         "result" => array()
        //     }
        //
        // Handle PONG response - Binance-style API returns array("result" => array()) for PING
        $result = $this->safe_value($message, 'result');
        if ($result !== null) {
            $eventType = $this->safe_string($message, 'e');
            $id = $this->safe_string($message, 'id');
            // If no $event and no $id, this is a PONG response
            if ($eventType === null && $id === null) {
                $this->handle_pong($client, $message);
                return;
            }
        }
        $event = $this->safe_string($message, 'e');
        $methods = array(
            'depthUpdate' => array($this, 'handle_order_book'),
            'aggTrade' => array($this, 'handle_trades'),
            '24hrTicker' => array($this, 'handle_ticker'),
            'kline' => array($this, 'handle_ohlcv'),
            'ACCOUNT_UPDATE' => array($this, 'handle_account_update'),
            'ORDER_TRADE_UPDATE' => array($this, 'handle_order_update'),
        );
        $exacMethod = $this->safe_value($methods, $event);
        if ($exacMethod !== null) {
            $exacMethod($client, $message);
            return;
        }
        $data = $this->safe_list($message, 'data');
        if ($data !== null) {
            $this->handle_tickers($client, $message);
        }
    }

    public function handle_account_update(Client $client, $message) {
        $account = $this->safe_dict($message, 'a', array());
        $hasBalances = (is_array($account) && array_key_exists('B', $account));
        $hasPositions = (is_array($account) && array_key_exists('P', $account));
        if ($hasBalances) {
            $this->handle_balance($client, $message);
        }
        if ($hasPositions) {
            $this->handle_position($client, $message);
        }
    }

    public function handle_order_update(Client $client, $message) {
        $orderData = $this->safe_dict($message, 'o', array());
        $executionType = $this->safe_string($orderData, 'x');
        if ($executionType === 'TRADE') {
            $this->handle_my_trade($client, $message);
        }
        $this->handle_order($client, $message);
    }

    public function ping(Client $client) {
        return array(
            'method' => 'PING',
        );
    }

    public function handle_pong(Client $client, $message) {
        $client->lastPong = $this->milliseconds();
        return $message;
    }

    public function handle_error_message(Client $client, $message) {
        return $message;
    }

    public function request_id() {
        $requestId = $this->sum($this->safe_integer($this->options, 'requestId', 0), 1);
        $this->options['requestId'] = $requestId;
        return $requestId;
    }
}
